import os, sys
sys.path.insert(0, os.getcwd())
import sqlite3
from src.repository import initialize, balance
from src.service import transfer
from src.events import Recorder

def setup():
    c = sqlite3.connect(":memory:")
    initialize(c)
    c.executemany("INSERT INTO accounts VALUES (?, ?)", [("a", 100), ("b", 20)])
    c.commit()
    return c

def state(c):
    return (balance(c, "a"), balance(c, "b"), c.execute("SELECT count(*) FROM ledger").fetchone()[0])

for args in [("a","a",1),("a","x",1),("x","a",1),("a","b",0),("a","b",-1),("a","b",True),("a","b",1.0),("a","b",101)]:
    c = setup(); p = Recorder()
    try: transfer(c, p, *args); raise SystemExit("no error %r" % (args,))
    except ValueError: pass
    assert state(c) == (100, 20, 0) and p.events == [] and not c.in_transaction

c = setup(); p = Recorder(); transfer(c, p, "a", "b", 100)
assert state(c) == (0, 120, 1) and len(p.events) == 1

class Bad:
    def publish(self, e): raise RuntimeError("x")
c = setup()
try: transfer(c, Bad(), "a", "b", 5); raise SystemExit("no error")
except RuntimeError: pass
assert state(c) == (95, 25, 1) and not c.in_transaction

class Conn:
    def __init__(self, c, fail): self.c, self.fail = c, fail
    def execute(self, sql, *a):
        if self.fail in sql: raise sqlite3.OperationalError("boom")
        return self.c.execute(sql, *a)
    def commit(self):
        if self.fail == "COMMIT": raise sqlite3.OperationalError("boom")
        self.c.commit()
    def rollback(self): self.c.rollback()
for fail in ["UPDATE accounts SET balance=balance-", "UPDATE accounts SET balance=balance+", "INSERT", "COMMIT"]:
    c = setup(); p = Recorder()
    try: transfer(Conn(c, fail), p, "a", "b", 5); raise SystemExit("no error")
    except sqlite3.OperationalError: pass
    assert state(c) == (100, 20, 0) and p.events == [], fail
print("ok")

